CREATE TABLE photo (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,resource_id UUID NOT NULL,capture_time TIMESTAMPTZ,capture_time_local VARCHAR(64),time_zone VARCHAR(64),width INTEGER,height INTEGER,orientation INTEGER,camera_make VARCHAR(256),camera_model VARCHAR(256),lens_model VARCHAR(256),latitude VARCHAR(64),longitude VARCHAR(64),version BIGINT NOT NULL DEFAULT 0,CHECK(width IS NULL OR width>0),CHECK(height IS NULL OR height>0),FOREIGN KEY(resource_id) REFERENCES resource(id),UNIQUE(owner_id,resource_id));
CREATE TABLE photo_asset (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,photo_id UUID NOT NULL,attachment_id UUID NOT NULL,role VARCHAR(32) NOT NULL,is_primary BOOLEAN NOT NULL DEFAULT FALSE,availability VARCHAR(32) NOT NULL DEFAULT 'AVAILABLE',version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(photo_id) REFERENCES photo(id) ON DELETE CASCADE,FOREIGN KEY(attachment_id) REFERENCES attachment(id),UNIQUE(photo_id,attachment_id),UNIQUE(photo_id,role));
CREATE UNIQUE INDEX uk_photo_primary_asset ON photo_asset(photo_id) WHERE is_primary=TRUE;
CREATE TABLE photo_album (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,name VARCHAR(512) NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE photo_album_member (id UUID PRIMARY KEY DEFAULT uuid_v7(),album_id UUID NOT NULL,photo_id UUID NOT NULL,added_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,FOREIGN KEY(album_id) REFERENCES photo_album(id) ON DELETE CASCADE,FOREIGN KEY(photo_id) REFERENCES photo(id),UNIQUE(album_id,photo_id));
CREATE INDEX idx_photo_capture_time ON photo(owner_id,capture_time DESC);
